/**
 * Personal API tokens. Only a hash of the secret is stored.
 */
import { and, desc, eq, isNull } from "drizzle-orm";
import { newId } from "@/lib/id";
import { apiTokens, getDb } from "@/server/db";
import { orgPredicate } from "./base-repository";
import { brandId, brandStamp, brandStampOrNull } from "./_mappers";
import type { ApiTokenRow } from "@/server/db/schema/api-tokens";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { ApiToken, ApiTokenScope } from "@/types/api-token";

export function toApiToken(row: ApiTokenRow): ApiToken {
  return {
    id: row.id,
    orgId: brandId<OrgId>(row.orgId),
    userId: brandId<UserId>(row.userId),
    name: row.name,
    scope: row.scope,
    prefix: row.prefix,
    expiresAt: brandStamp(row.expiresAt),
    lastUsedAt: brandStampOrNull(row.lastUsedAt),
    revokedAt: brandStampOrNull(row.revokedAt),
    createdAt: brandStamp(row.createdAt),
  };
}

export async function insertToken(input: {
  orgId: OrgId;
  userId: UserId;
  name: string;
  scope: ApiTokenScope;
  prefix: string;
  tokenHash: string;
  expiresAt: IsoTimestamp;
  createdAt: IsoTimestamp;
}): Promise<ApiToken> {
  const row = getDb()
    .insert(apiTokens)
    .values({ id: newId(), ...input, lastUsedAt: null, revokedAt: null })
    .returning()
    .get();
  return toApiToken(row);
}

/** Tokens that are neither revoked nor expired at `now`. */
export async function countUsableTokens(
  orgId: OrgId,
  userId: UserId,
  now: IsoTimestamp,
): Promise<number> {
  return getDb()
    .select()
    .from(apiTokens)
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.userId, userId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .all()
    .filter((row) => row.expiresAt > now).length;
}

export async function listTokens(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ApiToken[]> {
  return getDb()
    .select()
    .from(apiTokens)
    .where(
      and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.userId, userId)),
    )
    .orderBy(desc(apiTokens.createdAt), desc(apiTokens.id))
    .all()
    .map(toApiToken);
}

export async function listUnrevokedTokens(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ApiToken[]> {
  return getDb()
    .select()
    .from(apiTokens)
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.userId, userId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .all()
    .map(toApiToken);
}

export async function findToken(
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)))
    .get();
  return row ? toApiToken(row) : null;
}

/** Cross-tenant by design: the secret alone identifies the org. */
export async function findTokenByHash(
  tokenHash: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(eq(apiTokens.tokenHash, tokenHash))
    .get();
  return row ? toApiToken(row) : null;
}

export async function markRevoked(
  orgId: OrgId,
  tokenId: string,
  at: IsoTimestamp,
): Promise<ApiToken | null> {
  const row = getDb()
    .update(apiTokens)
    .set({ revokedAt: at })
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.id, tokenId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .returning()
    .get();
  return row ? toApiToken(row) : null;
}

export async function touchLastUsed(
  orgId: OrgId,
  tokenId: string,
  at: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(apiTokens)
    .set({ lastUsedAt: at })
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)))
    .run();
}
