/**
 * Personal API tokens for scripts and CI.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, hashToken, randomToken, hasRoleAtLeast
 */
import { emit, subscribe } from "@/lib/event-bus";
import { hashToken, randomToken } from "@/lib/hash";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import { createApiTokenSchema } from "@/schemas/api-token";
import * as tokenRepo from "@/server/repositories/api-token-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { toIsoTimestamp } from "@/types/common";
import { hasRoleAtLeast } from "@/types/member";
import { NotFoundError, actorEnvelope, envelope, orgResource } from "./_support";
import type { CreateApiTokenInput } from "@/schemas/api-token";
import type { ApiToken } from "@/types/api-token";
import type { OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor, Role } from "@/types/member";

const MAX_USABLE_TOKENS = 5;
const SECRET_PREFIX = "tfk_";
const PREFIX_LENGTH = 12;
const DAY_MS = 24 * 60 * 60 * 1000;

/** Role gates, expressed through existing permission actions of that rank. */
function assertRole(actor: Actor, atLeast: Role): void {
  assertCan(
    actor,
    atLeast === "member" ? "issue:create" : "org:update",
    orgResource(actor.orgId),
  );
}

export async function createApiToken(
  actor: Actor,
  input: CreateApiTokenInput,
): Promise<{ token: string; apiToken: ApiToken }> {
  const data = createApiTokenSchema.parse(input);
  assertOrgScope(actor, data.orgId);
  if (data.scope === "write") assertRole(actor, "member");

  const now = new Date();
  const usable = await tokenRepo.countUsableTokens(
    actor.orgId,
    actor.userId,
    toIsoTimestamp(now),
  );
  if (usable >= MAX_USABLE_TOKENS) {
    throw new Error(
      `You can hold at most ${MAX_USABLE_TOKENS} active API tokens per organization`,
    );
  }

  const token = `${SECRET_PREFIX}${randomToken(32)}`;
  const apiToken = await tokenRepo.insertToken({
    orgId: actor.orgId,
    userId: actor.userId,
    name: data.name,
    scope: data.scope,
    prefix: token.slice(0, PREFIX_LENGTH),
    tokenHash: hashToken(token),
    expiresAt: toIsoTimestamp(new Date(now.getTime() + data.expiresInDays * DAY_MS)),
    createdAt: toIsoTimestamp(now),
  });

  await emit("api_token.created", {
    ...actorEnvelope(actor),
    tokenId: apiToken.id,
    name: apiToken.name,
    scope: apiToken.scope,
  });

  return { token, apiToken };
}

export async function listApiTokens(
  actor: Actor,
  orgId: OrgId,
  userId?: UserId,
): Promise<readonly ApiToken[]> {
  assertOrgScope(actor, orgId);
  const target = userId ?? actor.userId;
  if (target !== actor.userId) assertRole(actor, "admin");
  return tokenRepo.listTokens(orgId, target);
}

export async function revokeApiToken(
  actor: Actor,
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken> {
  assertOrgScope(actor, orgId);
  const existing = await tokenRepo.findToken(orgId, tokenId);
  if (existing === null) throw new NotFoundError("ApiToken", tokenId);
  if (existing.userId !== actor.userId) assertRole(actor, "admin");
  if (existing.revokedAt !== null) return existing;

  return revokeAndAnnounce(existing, actor.userId);
}

async function revokeAndAnnounce(
  token: ApiToken,
  actorId: UserId,
): Promise<ApiToken> {
  const revoked = await tokenRepo.markRevoked(
    token.orgId,
    token.id,
    toIsoTimestamp(new Date()),
  );
  if (revoked === null) return (await tokenRepo.findToken(token.orgId, token.id)) ?? token;

  await emit("api_token.revoked", {
    ...envelope(token.orgId, actorId),
    tokenId: revoked.id,
    name: revoked.name,
  });
  return revoked;
}

export async function authenticateApiToken(token: string): Promise<Actor | null> {
  const found = await tokenRepo.findTokenByHash(hashToken(token));
  if (found === null || found.revokedAt !== null) return null;

  const now = toIsoTimestamp(new Date());
  if (found.expiresAt <= now) return null;

  const org = await orgRepo.findOrgById(found.orgId);
  if (org === null || org.archivedAt) return null;

  const member = await memberRepo.findMember(found.orgId, found.userId);
  if (member === null || member.status !== "active") return null;

  await tokenRepo.touchLastUsed(found.orgId, found.id, now);

  return {
    userId: found.userId,
    orgId: found.orgId,
    role: found.scope === "read" ? "viewer" : member.role,
  };
}

/** Revokes a removed member's remaining tokens. Called once from `event-registry`. */
export function registerApiTokenListeners(): Unsubscribe {
  return subscribe("member.removed", async (payload) => {
    const tokens = await tokenRepo.listUnrevokedTokens(payload.orgId, payload.userId);
    for (const token of tokens) {
      await revokeAndAnnounce(token, payload.actorId ?? payload.userId);
    }
  });
}
